15|pub(super) fn verify_partition(
16|    device: &File,
17|    image: &File,
18|    backing: &std::fs::Metadata,
19|    layout: &PartitionedOverlay,
20|    number: u8,
21|) -> Result<File> {
22|    let pin = match number { 1 => &layout.root_partition, 2 => &layout.upgrade_partition,
23|        _ => anyhow::bail!("unsupported identity partition") };
24|    let mut header = [0u8; 92];
25|    image.read_exact_at(&mut header, 512)?;
26|    let header_crc = u32::from_le_bytes(header[16..20].try_into()?);
27|    header[16..20].fill(0);
28|    ensure!(&header[..8] == b"EFI PART" && u32::from_le_bytes(header[8..12].try_into()?) == 0x10000
29|        && u32::from_le_bytes(header[12..16].try_into()?) == 92 && crc32(&header) == header_crc
30|        && u64::from_le_bytes(header[24..32].try_into()?) == 1
31|        && u64::from_le_bytes(header[32..40].try_into()?) == backing.len() / 512 - 1
32|        && uuid::Uuid::from_bytes_le(header[56..72].try_into()?).to_string() == layout.disk_guid
33|        && u64::from_le_bytes(header[72..80].try_into()?) == 2
34|        && u32::from_le_bytes(header[80..84].try_into()?) == 128
35|        && u32::from_le_bytes(header[84..88].try_into()?) == 128,
36|        "protected image GPT header differs");
37|    let mut table = [0u8; 16384];
38|    image.read_exact_at(&mut table, 1024)?;
39|    ensure!(crc32(&table) == u32::from_le_bytes(header[88..92].try_into()?)
40|        && table[256..].iter().all(|byte| *byte == 0), "GPT is corrupt or includes another partition");
41|    let entry = &table[(usize::from(number) - 1) * 128..usize::from(number) * 128];
42|    ensure!(uuid::Uuid::from_bytes_le(entry[..16].try_into()?).to_string()
43|            == "0fc63daf-8483-4772-8e79-3d69d8477de4"
44|        && uuid::Uuid::from_bytes_le(entry[16..32].try_into()?).to_string() == pin.partuuid
45|        && u64::from_le_bytes(entry[32..40].try_into()?) == pin.start_sector
46|        && u64::from_le_bytes(entry[40..48].try_into()?).checked_add(1)
47|            == pin.start_sector.checked_add(pin.sectors), "GPT partition pin differs");
48|    let meta = device.metadata()?;
49|    ensure!(meta.file_type().is_block_device(), "partition is not a block device");
50|    let sysfs = format!("/sys/dev/block/{}:{}", libc::major(meta.rdev()), libc::minor(meta.rdev()));
51|    let kernel_name = std::fs::read_link(&sysfs)?;
52|    let kernel_name = kernel_name.file_name().and_then(|name| name.to_str()).context("partition name unavailable")?;
53|    let suffix = format!("p{number}");
54|    let loop_name = kernel_name.strip_suffix(&suffix).context("wrong loop partition number")?;
55|    let loop_number = loop_name.strip_prefix("loop").context("partition parent is not loop storage")?;
56|    ensure!(!loop_number.is_empty() && loop_number.bytes().all(|byte| byte.is_ascii_digit()), "invalid loop parent");
57|    for (field, expected) in [("partition", u64::from(number)), ("start", pin.start_sector), ("size", pin.sectors)] {
58|        let value = std::fs::read_to_string(format!("{sysfs}/{field}"))?;
59|        ensure!(value.len() <= 32 && value.trim().parse::<u64>()? == expected, "kernel partition geometry differs");
60|    }
61|    let parent = open(Path::new(&format!("/dev/{loop_name}")), false)?;
62|    let mut status: LoopInfo = unsafe { std::mem::zeroed() };
63|    // SAFETY: held loop descriptor and ABI-sized LOOP_GET_STATUS64 output.
64|    ensure!(unsafe { libc::ioctl(parent.as_raw_fd(), 0x4c05 as libc::c_ulong, &mut status) } == 0
65|        && status.number.to_string() == loop_number && loop_matches(&status, backing, false),
66|        "partition loop does not own the pinned image");
67|    Ok(parent)
