88|fn readonly_overlay(path: &Path) -> Result<()> {
89|    let mut found = false;
90|    let mounts = std::fs::read_to_string("/proc/self/mountinfo")?;
91|    for line in mounts.lines() {
92|        let Some((left, right)) = line.split_once(" - ") else { continue; };
93|        let left = left.split_whitespace().collect::<Vec<_>>();
94|        let right = right.split_whitespace().collect::<Vec<_>>();
95|        if left.get(4).copied() != path.to_str() { continue; }
96|        ensure!(left.get(5).is_some_and(|options| options.split(',').any(|option| option == "ro"))
97|            && right.first() == Some(&"overlay"), "guest root is not a read-only overlay");
98|        let expected = "lowerdir=/var/lib/3tched-leaf-pool/.mounts/3tchedChatbot/upgrade-layer:/var/lib/3tched-leaf-pool/.mounts/3tchedChatbot/seed-layer";
99|        ensure!(right.get(2).is_some_and(|options| options.split(',').any(|option| option == expected)),
100|            "overlay layers differ from the pinned identity");
101|        found = true;
102|    }
103|    ensure!(found, "overlay mount absent");
104|    Ok(())
